INSERT INTO `departments` (`id`, `name`, `slug`, `description`, `image`, `created_at`, `updated_at`) VALUES (1,'DEPARTMENT OF HEALTH SCIENCES.','department-of-health-sciences','The Department of Health Sciences at HBIC is dedicated to training skilled, compassionate, and job-ready professionals to meet the growing healthcare needs of Kenya and the region. Our programs are designed to blend theoretical knowledge with practical, community-based experience, equipping students to serve effectively in hospitals, public health departments, NGOs, and grassroots health initiatives.\r\n\r\nWe focus on producing graduates who are not only technically competent but also ethically grounded and passionate about improving health outcomes in their communities.','department_images/sjSJSCpVrct4XKpLJmwuYO9a2nsOe97cOe9OymFe.jpg','2025-07-31 07:36:30','2025-07-31 07:36:30'),(2,'DEPARTMENT OF APPLIED & LABORATORY SCIENCES.','department-of-applied-laboratory-sciences','SCIENCE THAT SAVES LIVES\r\nThe Department of Applied & Laboratory Sciences at HBIC offers specialized programs designed to equip students with the technical skills, scientific knowledge, and hands-on experience required in medical laboratories, research facilities, biotechnology labs, and diagnostic centers.\r\n\r\nOur programs are aligned with industry standards and national health priorities, preparing graduates to perform critical roles in medical testing, biomedical innovation, and public health research. Whether you’re interested in lab diagnostics, biotechnology, or medical engineering, this department provides a strong foundation for a high-demand career in the health sciences sector.','department_images/rRxpganq4c91fdAsru7uxT01QkC987QBbZ66Lse9.jpg','2025-07-31 08:35:29','2025-07-31 08:35:29'),(3,'CLINICAL & ALLIED HEALTH','clinical-allied-health','HANDS-ON SKILLS FOR LIFE-SAVING CAREERS.\r\nThe Department of Clinical & Allied Health at HBIC offers a diverse range of programs that prepare students for frontline clinical and technical roles in the healthcare system. From operating theatre support to diagnostic imaging, mortuary science, and dental technology, our programs are designed to meet the growing demand for specialized healthcare professionals in Kenya and beyond.\r\n\r\nWith a focus on practical training, ethics, and clinical excellence, this department nurtures job-ready graduates who are vital to surgical teams, diagnostic units, and patient care services across hospitals, clinics, and public health institutions.','department_images/Pw8IA0AKEIF2yhuYaB8gmBpnCpB2gH20xStp8k3n.jpg','2025-07-31 08:49:33','2025-07-31 08:49:33'),(4,'Department of German Studies','department-of-german-studies','GERMAN LANGUAGE.\r\nExperienced Teaching ensures your success.\r\n\r\nLearn German from the market leader. We offer German language courses and exams.\r\n\r\n> Highly qualified German teachers and first-class learning materials\r\n> German courses for all levels\r\n> Internationally recognised German certificates','department_images/uGoMecA18ZFTl1Y2X9NLDLKq00Hl8R1Ay422I0dw.jpg','2025-08-21 17:42:24','2025-08-21 17:42:24'),(5,'HOSPITALITY','hospitality','Barita and Mixology',NULL,'2025-09-09 14:11:56','2025-09-09 14:11:56'),(6,'AVIATION','aviation','Ready for a career that takes you to the skies?\r\n\r\nOur Cabin Crew Certificate Course is your first step toward an exciting and dynamic career in aviation. Learn essential safety, service, and communication skills from industry experts in our hands-on training environment. Get ready to embark on your global career with Hewitt and Bennet International College.',NULL,'2025-09-09 15:10:38','2025-09-09 15:10:38');
INSERT INTO `courses` (`id`, `department_id`, `name`, `slug`, `school_fees`, `registration_fees`, `duration`, `course_description`, `image`, `school_uniform_fee`, `created_at`, `updated_at`) VALUES (1,1,'Certificate in Health Service Support','certificate-in-health-service-support',0.00,3000.00,'12 Months','To equip students with the foundational knowledge and practical skills required to assist nurses, doctors and other healthcare providers quality patient care and maintaining a safe  and efficient healthcare environment','course_images/X2RRLnROaoYjmdOVcSmOALWDWgZAfEYDrVPhQ0Dw.jpg',0.00,'2025-07-31 09:57:26','2025-11-08 09:38:09'),(2,1,'TVET CDACC CAREGIVING COURSE','tvet-cdacc-caregiving-course',0.00,3000.00,'6 Months','Our comprehensive Caregiving Course equips you with the essential skills and knowledge to provide exceptional care for individuals in need. Learn practical techniques for daily support, personal care, medication assistance, and effective communication, all while fostering empathy and understanding. Ideal for aspiring caregivers, family members, or anyone looking to make a meaningful difference.','course_images/rVW8ROPjtt6s0ZfbSQiSLyIF2PYMALdgppjbw3nL.jpg',0.00,'2025-07-31 11:57:13','2025-11-08 09:38:41'),(3,1,'TVET CDACC HOMEBASED CARE','tvet-cdacc-homebased-care',0.00,3000.00,'4 Months','Our Home-Based Care Course is designed to equip individuals with the essential knowledge and practical skills needed to provide compassionate and effective care for clients in their own homes. This program covers a comprehensive range of topics, including personal care, medication management, first aid, basic nursing procedures, infection control, nutrition, and communication techniques. You\'ll also learn about common health conditions, safety protocols, and how to provide emotional and social support. Whether you\'re looking to start a rewarding career in home healthcare or care for a loved one, this course will prepare you to offer high-quality, personalized care with confidence and professionalism.','course_images/yG9Yoh4V5YPYi2hnMQ4JB6hrMb9FNBeOD91V5bSR.jpg',0.00,'2025-07-31 12:16:06','2025-11-08 09:53:17'),(4,1,'Certificate in Peri-operative Theatre Technology','certificate-in-peri-operative-theatre-technology',0.00,3000.00,'12 Months','This comprehensive Certificate program in Peri-operative Theatre Technology equips students with the essential knowledge and practical skills required to work as a valuable member of the surgical team. Graduates will be proficient in assisting surgeons, anaesthetists, and nurses in all phases of peri-operative care, including preparing the operating room, sterilizing instruments, maintaining a sterile field, and ensuring patient safety during surgical procedures. This course is ideal for individuals seeking a dynamic and crucial role in healthcare, directly contributing to successful surgical outcomes.','course_images/OBtYYZflkC6DieeJoVTU3myhVsBPEzRro8o6Lr6Q.jpg',0.00,'2025-07-31 12:30:35','2025-11-08 09:56:36'),(5,1,'Diploma In Peri-Operative Theatre Technology','diploma-in-peri-operative-theatre-technology',0.00,3000.00,'24 Months','This Diploma in Peri-operative Theatre Technology program equips students with the essential knowledge and practical skills required to work as a vital member of the surgical team. Graduates will be proficient in preparing operating theaters, sterilizing instruments, assisting surgeons during procedures, and providing pre- and post-operative patient care within the theatre environment. The course emphasizes patient safety, infection control, and the effective use of theatre equipment, preparing students for a dynamic and rewarding career in healthcare.','course_images/vZAatTdzcAdK7OugMnrZ45eowz8qV553fyj6Ldqi.jpg',0.00,'2025-07-31 13:11:34','2025-11-08 11:12:40'),(6,1,'Certificate In Emergency Medical Technician ( EMT)','certificate-in-emergency-medical-technician-emt',0.00,3000.00,'12 Months','Our comprehensive Emergency Medical Technician (EMT) certificate program provides students with the essential knowledge and hands-on skills required to provide immediate, life-saving care in pre-hospital settings. This course covers critical topics such as patient assessment, trauma management, medical emergencies, airway management, CPR, pharmacology, and incident command. Taught by experienced professionals, our program emphasizes practical application and critical thinking, preparing graduates to excel as certified EMTs and make a vital difference in their communities. Upon successful completion, students will be eligible to sit for national certification examinations.','course_images/oaOXaHm9xnLlNZFoHqIRLXs3H3dZuhzO8KhzlFQT.jpg',0.00,'2025-07-31 13:35:26','2025-11-08 11:14:14'),(7,1,'Diploma In Emergency Medical Technician ( EMT)','diploma-in-emergency-medical-technician-emt',0.00,3000.00,'24 Months','Our Diploma in Emergency Medical Technician (EMT) program equips students with essential skills to provide immediate, life-saving care in pre-hospital settings. Learn to assess patients, administer critical interventions, and safely transport individuals facing medical emergencies or trauma. Become a vital first responder.','course_images/lhql3cBGQwl1Fv4Ble8LT2KfWu9rscEsbf1DJMx1.jpg',0.00,'2025-07-31 13:43:04','2025-11-08 11:15:06'),(8,1,'Certificate in Medical Imaging & Infomatics','certificate-in-medical-imaging-infomatics',0.00,3000.00,'12 Months','This Certificate in Medical Imaging and Informatics course is designed to equip students with essential skills in the rapidly evolving field where medical imaging meets information technology. You\'ll gain a fundamental understanding of how digital medical images are created, processed, managed, and utilized to enhance patient care and diagnostics.','course_images/fAZb75jZOiuXeopzYwpOXHIdInumj4ISyOj6ckkG.jpg',0.00,'2025-07-31 15:23:52','2025-11-08 11:17:08'),(9,4,'German Language','german-language',0.00,3000.00,'3 months','GERMAN LANGUAGE.\r\n\r\nExperienced Teaching ensures your success.\r\nLearn German from the market leader. We offer German language courses and exams.\r\n\r\n> Highly qualified German teachers and first-class learning materials\r\n> German courses for all levels\r\n> Internationally recognised German certificates','course_images/sRP7gpvobhJUUEKcnmi13GIUvXkAbcIEsjzsUClX.jpg',0.00,'2025-08-21 18:06:01','2025-08-21 18:06:01'),(10,1,'Certificate in Mortuary Science','certificate-in-mortuary-science',0.00,0.00,'1 year','The Mortuary Science course at Hewitt and Bennet International College equips learners with essential knowledge and hands-on experience in the field of funeral service and human remains management. This program offers a solid foundation in mortuary operations, embalming techniques, grief counseling basics, public health regulations, and ethical conduct related to end-of-life care.\r\n\r\nLearners are exposed to both classroom instruction and intensive practical training to prepare them for work in hospitals, funeral homes, county morgues, and disaster response units.','course_images/YJy0eprgTXeLZFCSsejPqUrn46z0RJUwIvG9IGuK.jpg',0.00,'2025-09-09 12:50:09','2025-11-08 11:16:00'),(11,1,'Phlebotomy','phlebotomy',0.00,0.00,'3 Months','This short course provides foundational knowledge and hands-on skills in phlebotomy, preparing healthcare workers to perform safe, ethical, and accurate blood specimen collection. The course follows a blended approach, combining online theory with supervised practical experience.','course_images/RgCcurU5C2W5FzLgAMGHPkXJJfkHCPsi5imnnq7m.jpg',0.00,'2025-09-09 12:57:02','2025-11-08 11:17:37'),(12,5,'Mixology','mixology',0.00,0.00,'6 Months','The mixology course is a comprehensive program designed to take students from a basic understanding of bartending to a high level of expertise in the art and science of cocktails. It\'s much more in-depth than a short, introductory course and often includes a blend of theoretical and practical training.','course_images/ThSJOJKIJIdkywMB8uhoXDDJ32sVmosBdi42DMkD.png',0.00,'2025-09-09 14:14:19','2025-11-08 11:19:54'),(13,5,'Barista','barista',0.00,0.00,'6 Months','This course offers a comprehensive and immersive exploration into the world of coffee, designed for aspiring baristas and coffee enthusiasts. From the history of the coffee bean to the perfect pour, you will learn the art and science behind crafting exceptional coffee beverages.','course_images/05eWfHt1OE7hFchRUBSFyYERQYAwvL1AHpZPN8Gr.png',0.00,'2025-09-09 14:18:55','2025-11-08 11:20:42'),(14,5,'Barista and Mixology','barista-and-mixology',0.00,0.00,'6 Months','Elevate your hospitality skills with our intensive Barista & Mixology Masterclass, a dual-certification program designed for those aspiring to master both the art of coffee and the craft of cocktails. This comprehensive course provides an in-depth exploration of two dynamic beverage worlds, equipping you with versatile skills for any high-end cafe, bar, or restaurant.','course_images/N9JafnELVEsgUPJcLJgmstx4vkXnl0wb8srE7Q7n.png',0.00,'2025-09-09 14:25:35','2025-11-08 11:21:14'),(15,6,'Cabin Crew','cabin-crew',0.00,3000.00,'6 Months','Ready for a career that takes you to the skies?\r\n\r\nOur Cabin Crew Certificate Course is your first step toward an exciting and dynamic career in aviation. Learn essential safety, service, and communication skills from industry experts in our hands-on training environment. Get ready to embark on your global career with Hewitt and Bennet International College.','course_images/83FWZ67JERDWKqXnv7OTxZtYYzkQrCR1DETPX77J.jpg',0.00,'2025-09-09 15:12:32','2025-11-08 11:21:37');
